// ── Tokenisation and embedding concepts ────────────────────────
// Simplified illustration — real BPE tokenisers use learned merge rules

// Simplified tokeniser vocabulary (in practice, GPT-4o has ~100k tokens)
const vocab = {
  'Hello': 1, ',': 2, ' ': 3, 'world': 4, '!': 5,
  'The': 6, 'cat': 7, 'sat': 8, 'on': 9, 'mat': 10,
  '<PAD>': 0, '<EOS>': 11
};
const idToToken = Object.fromEntries(Object.entries(vocab).map(([k,v]) => [v,k]));

function tokenise(text) {
  // Naive whitespace + punctuation split for demo
  return text.match(/[\w]+|[^\w\s]/g).map(t => vocab[t] ?? -1);
}

console.log('Token IDs:', tokenise('Hello , world !'));
// [1, 2, 4, 5]  (space is usually merged into next token in real BPE)

// ── Tiny attention mechanism ────────────────────────────────────
// scaled dot-product attention: softmax(Q K^T / sqrt(d_k)) V

function softmax(arr) {
  const maxVal = Math.max(...arr);
  const exps = arr.map(x => Math.exp(x - maxVal)); // numerically stable
  const sum = exps.reduce((a, b) => a + b, 0);
  return exps.map(e => e / sum);
}

function dotProduct(a, b) {
  return a.reduce((s, v, i) => s + v * b[i], 0);
}

// 3 tokens, dimension d_k=2 for illustration
const queries = [[1, 0], [0, 1], [1, 1]];
const keys    = [[1, 0], [0, 1], [0, 0]];
const values  = [[10, 0], [0, 10], [5, 5]];
const dk = 2;

// Attention for token 0: how much does it attend to each position?
const scores0 = keys.map(k => dotProduct(queries[0], k) / Math.sqrt(dk));
const weights0 = softmax(scores0);
const output0 = values[0].map((_, i) =>
  weights0.reduce((s, w, j) => s + w * values[j][i], 0)
);

console.log('Attention weights for token 0:', weights0.map(w => w.toFixed(3)));
console.log('Attended output for token 0:',  output0.map(v => v.toFixed(2)));
// Token 0 (query=[1,0]) matches key 0 ([1,0]) strongly → mostly attends to value 0

// ── Context window and token counting ──────────────────────────
function estimateTokens(text) {
  // Rough estimate: 1 token ≈ 0.75 words, or 1 token ≈ 4 characters
  const wordCount = text.trim().split(/\s+/).length;
  const charCount = text.length;
  return {
    byWords: Math.ceil(wordCount / 0.75),
    byChars: Math.ceil(charCount / 4)
  };
}

const sample = 'The quick brown fox jumps over the lazy dog';
console.log('Token estimate:', estimateTokens(sample));
// byWords: 12, byChars: 11  (actual GPT-4o: 10 tokens)

// ── LLM Vocabulary ─────────────────────────────────────────────
//
// TOKEN
//   Atomic text unit. ~0.75 words on average.
//   'unhappiness' → ['un', 'happ', 'iness'] (3 tokens)
//   Token ID is an integer index into the vocabulary.
//
// EMBEDDING
//   Token ID → dense vector (e.g. 4096-dim for LLaMA 3 8B).
//   Learned: semantically similar tokens cluster nearby.
//   + positional encoding so model knows order.
//
// ATTENTION
//   For each token, compute weighted sum of all other tokens' values.
//   Weights = softmax(Q * K^T / sqrt(d_k))
//   Multi-head: run H attention heads in parallel, concatenate.
//   Allows global, selective, position-independent context mixing.
//
// TRANSFORMER BLOCK
//   Multi-head self-attention → Add+Norm → Feed-forward → Add+Norm
//   GPT-4 reportedly has 128 layers, d_model=12288, 96 heads.
//
// CONTEXT WINDOW
//   Max tokens in one forward pass. Beyond this = invisible.
//   GPT-4o: 128k. Claude 3.5 Sonnet: 200k. Gemini 1.5 Pro: 2M.
//
// TRAINING vs INFERENCE
//   Training: weights update via backprop on next-token prediction.
//   Inference: weights frozen; new tokens generated autoregressively.
//
// TEMPERATURE
//   Scales logits before softmax: low temp → peaked (deterministic),
//   high temp → flat (more random). temp=0 → greedy decoding.
//
// RLHF (Reinforcement Learning from Human Feedback)
//   Fine-tunes LLMs to follow instructions and be helpful/harmless.
//   Human raters rank model outputs; reward model trained on ranks;
//   LLM updated via PPO to maximise reward model score.
//
// KV-CACHE
//   During inference, Key and Value matrices from previous tokens
//   are cached so they are not recomputed on each new token generation.
//   Critical optimisation — without it, generation is O(n^2) per token.
